import{_ as a,o as _,c as $,a2 as t}from"./chunks/framework.F7eQ-ohH.js";const c="/bzygq/assets/quesion_imgs_0fdbd2d1c94f47568f882b2c0ab7ec3d.CGZqQGVK.png",e="/bzygq/assets/quesion_imgs_a098a34cc04243218319d7a95f1a0d15.D-4sfbJv.png",p="/bzygq/assets/quesion_imgs_7c0f197e5ca148bfa6d7575486b3c301.CEHwhuHt.png",u=JSON.parse('{"title":"几何问题","description":"","frontmatter":{},"headers":[],"relativePath":"行测/数量分析/6.几何问题.md","filePath":"行测/数量分析/6.几何问题.md","lastUpdated":1788883925000}'),s={name:"行测/数量分析/6.几何问题.md"};function i(o,r,d,h,f,n){return _(),$("div",null,[...r[0]||(r[0]=[t('<h1 id="几何问题" tabindex="-1">几何问题 <a class="header-anchor" href="#几何问题" aria-label="Permalink to &quot;几何问题&quot;">​</a></h1><p>在这里开始编写您的内容...几何问题的考察内容主要包括几何图形的面积、体积的计算和定理的应用等等，关键点在于掌握几何运算的公式和解题的方式方法。</p><h2 id="平面图形的周长和面积" tabindex="-1">平面图形的周长和面积 <a class="header-anchor" href="#平面图形的周长和面积" aria-label="Permalink to &quot;平面图形的周长和面积&quot;">​</a></h2><p><img src="'+c+'" alt=""></p><p>例1：已知下图中有两个正方形，边长分别是8cm、5cm，则阴影部分的面积是（）$$cm^2$$</p><p><img src="'+e+'" alt=""></p><p>A.52.5 B.57 C.54.5 D.55</p><p>解析：连接两个正方形的对角线，整个阴影部分的面积就等于上下两个三角形之和，因此， $$S=52.5$$ $$cm^2$$,所以本题选A。</p><ol start="2"><li>立体图形的表面积和体积</li></ol><p><img src="'+p+'" alt=""></p><p><strong>例2：两个侧面积相等的圆柱，他们的体积之比为$$V_1:V_2=4:3$$，则它们的底面积之比$$S_1:S_2$$为()。</strong> A.9:4 B.3:2 C.25:16 D.16:9</p><p>解析：设两个圆柱的底面半径分别为 $$r_1$$、$$r_2$$，高分别为 $$h_1$$、$$h_2$$，圆柱侧面积公式为 $$S_{\\text{侧}} = 2\\pi r h$$，由题意得：<br> $$2\\pi r_1 h_1 = 2\\pi r_2 h_2 \\quad \\Rightarrow \\quad r_1 h_1 = r_2 h_2 \\quad \\Rightarrow \\quad \\frac{h_1}{h_2} = \\frac{r_2}{r_1} \\quad \\text{①}$$</p><p>接着根据体积比列方程，圆柱体积公式为 $$V = \\pi r^2 h$$，已知体积比 $$V_1:V_2 = 4:3$$，则：<br> $$\\frac{\\pi r_1^2 h_1}{\\pi r_2^2 h_2} = \\frac{4}{3} \\quad \\Rightarrow \\quad \\frac{r_1^2 h_1}{r_2^2 h_2} = \\frac{4}{3} \\quad \\text{②}$$</p><p>最后代入①式化简求底面积比 将 $$h_1 = \\frac{r_2 h_2}{r_1}$$（由①式变形）代入②式：<br> $$\\frac{r_1^2 \\cdot \\frac{r_2 h_2}{r_1}}{r_2^2 h_2} = \\frac{4}{3} \\quad \\Rightarrow \\quad \\frac{r_1 r_2 h_2}{r_2^2 h_2} = \\frac{4}{3} \\quad \\Rightarrow \\quad \\frac{r_1}{r_2} = \\frac{4}{3}$$ 底面积公式为 $$S = \\pi r^2$$，因此底面积之比：<br> $$\\frac{S_1}{S_2} = \\frac{\\pi r_1^2}{\\pi r_2^2} = \\left( \\frac{r_1}{r_2} \\right)^2 = \\left( \\frac{4}{3} \\right)^2 = \\frac{16}{9}$$</p><p>答案：$$\\boxed{\\dfrac{16}{9}}$$</p>',15)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
